  array( 'module' => 'currency_per_product', 'group' => 'product-currency-update', 'label' => 'Product currency rate updates', 'consequence' => 'Choose manual or automatic updates for rates used by Currency per Product. Free uses manual updates; Plus and Elite can use the available automatic modes.', 'context' => 'Check each conversion rate after changing the mode or requesting an update. A schedule alone does not confirm a successful fetch. If a rate is wrong, correct it and resolve the provider issue before relying on automatic updates.', 'guide' => 'https://booster.io/docs/woocommerce-currency-per-product/#booster-v10-s18-product-currency-update', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product&active_tab=currency_per_product_exchange_rates_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product&active_tab=currency_per_product_exchange_rates_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product&active_tab=currency_per_product_exchange_rates_options_tab' ) ), 'members' => array( 'free' => array( 'Exchange Rates Updates (Free limit applies)' ), 'plus' => array( 'Exchange Rates Updates' ), 'elite' => array( 'Exchange Rates Updates' ) ) ),
  array( 'module' => 'currency_per_product', 'group' => 'product-currency-rows', 'label' => 'Currencies and matching rows', 'consequence' => 'Choose currencies, conversion rates and the products matched by each row. When rules overlap, the first applicable match can decide the product\'s currency.', 'context' => 'Free uses one row. Enable and save author, author-role, category or tag matching before filling those selectors. Check an overlapping product as well as a single-match product; restore the previous rows or selections if the wrong currency wins.', 'guide' => 'https://booster.io/docs/woocommerce-currency-per-product/#booster-v10-s18-product-currency-rows', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product&active_tab=currency_per_product_currencies_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product&active_tab=currency_per_product_currencies_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product&active_tab=currency_per_product_currencies_options_tab' ) ), 'members' => array( 'free' => array( 'Total Currencies (Free limit applies)', 'Currency', 'Conversion rate for each currency row', 'Product Authors', 'Product Authors User Roles', 'Product Categories', 'Product Tags' ), 'plus' => array( 'Total Currencies', 'Currency', 'Conversion rate for each currency row', 'Product Authors', 'Product Authors User Roles', 'Product Categories', 'Product Tags' ), 'elite' => array( 'Total Currencies', 'Currency', 'Conversion rate for each currency row', 'Product Authors', 'Product Authors User Roles', 'Product Categories', 'Product Tags' ) ) ),
  array( 'module' => 'currency_per_product', 'group' => 'product-currency-cache', 'label' => 'Reuse converted prices while a page loads', 'consequence' => 'Reuse a converted price when it is requested again while the current page is being generated. This option does not rewrite the product\'s stored price.', 'context' => 'Note the previous setting, then compare a product and cart after a rate change and on a freshly loaded page. If amounts disagree, return to the prior setting and review the conversion rate and other pricing features.', 'guide' => 'https://booster.io/docs/woocommerce-currency-per-product/#booster-v10-s18-product-currency-cache', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product&active_tab=currency_per_product_advanced_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product&active_tab=currency_per_product_advanced_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product&active_tab=currency_per_product_advanced_options_tab' ) ), 'members' => array( 'free' => array( 'Save Calculated Products Prices (reuse while a page loads)' ), 'plus' => array( 'Save Calculated Products Prices (reuse while a page loads)' ), 'elite' => array( 'Save Calculated Products Prices (reuse while a page loads)' ) ) ),
  array( 'module' => 'currency_per_product', 'group' => 'product-currency-meta', 'label' => 'This product currency', 'consequence' => 'Choose the currency for this product. Enabled author, author-role, category or tag rules can choose a currency before this product-level value is used.', 'context' => 'Check those rules before replacing a blank or unfamiliar value. After saving, open the product and add it to a test cart. If its currency is unexpected, restore the previous product choice and review the matching rule.', 'guide' => 'https://booster.io/docs/woocommerce-currency-per-product/#booster-v10-s18-product-currency-meta', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Product Currency' ), 'plus' => array( 'Product Currency' ), 'elite' => array( 'Product Currency' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-field', 'label' => 'VAT field wording and layout', 'consequence' => 'Set the VAT-number field\'s wording, position, appearance and whether a value is required. Requiring a number does not confirm that it is valid or that VAT should be removed.', 'context' => 'Use a clear label and explain why you ask for the number. Check an empty form and one with a sample number. If the requirement blocks buyers you intend to serve, restore the previous required-field choice.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-field', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ) ), 'members' => array( 'free' => array( 'Field Label', 'Placeholder', 'Description', 'Required', 'Clear', 'CSS class (styling name)' ), 'plus' => array( 'Field Label', 'Placeholder', 'Description', 'Required', 'Clear', 'CSS class (styling name)' ), 'elite' => array( 'Field Label', 'Placeholder', 'Description', 'Required', 'Clear', 'CSS class (styling name)' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-validation', 'label' => 'VAT validation', 'consequence' => 'Check VAT numbers using the selected validation method. An invalid number and an unavailable validation service are different problems; neither should be shown as a successful check.', 'context' => 'Choose the method and messages, then check valid, invalid and unavailable-service outcomes on a test store. Keep the previous method if the service cannot be reached. A valid number alone does not decide VAT exemption.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-validation', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ) ), 'members' => array( 'free' => array( 'Validate', 'Message on not valid', 'First Validation Method' ), 'plus' => array( 'Validate', 'Message on not valid', 'First Validation Method' ), 'elite' => array( 'Validate', 'Message on not valid', 'First Validation Method' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-exemption', 'label' => 'VAT exemption policy', 'consequence' => 'Choose when a valid or saved customer VAT number can lead to VAT being removed, including the cart-related options. A valid number alone does not make every order exempt.', 'context' => 'Match these choices to your tax policy and check country exceptions and customer conditions. Compare taxable and exempt test purchases. If tax is removed unexpectedly, restore the previous exemption choices before taking further orders.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-exemption', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ) ), 'members' => array( 'free' => array( 'Exempt VAT for Valid Numbers', 'Exempt VAT on Cart', 'Show VAT field for EU countries only (Free limit applies)', 'Exempt VAT by Customer\'s EU VAT' ), 'plus' => array( 'Exempt VAT for Valid Numbers', 'Exempt VAT on Cart', 'Show VAT field for EU countries only', 'Exempt VAT by Customer\'s EU VAT' ), 'elite' => array( 'Exempt VAT for Valid Numbers', 'Exempt VAT on Cart', 'Show VAT field for EU countries only', 'Exempt VAT by Customer\'s EU VAT' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-country-exceptions', 'label' => 'Base-country and location exceptions', 'consequence' => 'Keep VAT for selected billing or shipping matches with the store\'s base country, and choose checks against the shopper\'s IP-based location. These choices can change whether tax is charged.', 'context' => 'Check a same-country buyer and a cross-border buyer, including different billing and shipping addresses. IP location is an estimate, not proof of residence. Restore the previous exceptions if the tax result does not match your policy.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-country-exceptions', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ) ), 'members' => array( 'free' => array( 'Preserve VAT in Base Country By Billing country (Free limit applies)', 'Preserve VAT in Base Country By Shipping country (Free limit applies)', 'Check for IP Location Country (Free limit applies)' ), 'plus' => array( 'Preserve VAT in Base Country By Billing country', 'Preserve VAT in Base Country By Shipping country', 'Check for IP Location Country' ), 'elite' => array( 'Preserve VAT in Base Country By Billing country', 'Preserve VAT in Base Country By Shipping country', 'Check for IP Location Country' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-position', 'label' => 'VAT display placement', 'consequence' => 'Choose where the VAT number appears in checkout and order address details. This controls placement, not whether a number is valid or an order is tax-exempt.', 'context' => 'Save the position and inspect checkout and an order\'s address display. If it overlaps or repeats another field, restore the prior position and check your address layout.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-position', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_general_options_tab' ) ), 'members' => array( 'free' => array( 'Display' ), 'plus' => array( 'Display' ), 'elite' => array( 'Display' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-progress', 'label' => 'Validation progress messages', 'consequence' => 'Give shoppers different messages while a VAT check runs, succeeds, rejects a number or cannot reach the service. Clear wording helps them choose the next step.', 'context' => 'Check each outcome and tell buyers what to correct or when to retry. Never describe a service failure as a valid number. Restore the old message if the new wording hides the actual result.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-progress', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_messages_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_messages_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_messages_options_tab' ) ), 'members' => array( 'free' => array( 'Add Progress Messages', 'Progress Message: Validating', 'Progress Message: Valid', 'Progress Message: Not Valid', 'Progress Message: Validation Failed' ), 'plus' => array( 'Add Progress Messages', 'Progress Message: Validating', 'Progress Message: Valid', 'Progress Message: Not Valid', 'Progress Message: Validation Failed' ), 'elite' => array( 'Add Progress Messages', 'Progress Message: Validating', 'Progress Message: Valid', 'Progress Message: Not Valid', 'Progress Message: Validation Failed' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-admin-summary', 'label' => 'Administrative VAT summary', 'consequence' => 'Show a VAT-number summary when managing an order. Its Validate VAT and remove taxes action can change taxes on that existing order, not just check a number.', 'context' => 'Review the order\'s VAT number and tax lines before using any action. Keep an order record first. If you only want to inspect the number, do not use an action that also removes taxes.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-admin-summary', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_messages_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_messages_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_messages_options_tab' ) ), 'members' => array( 'free' => array( 'Show VAT-number summary on the order editing page' ), 'plus' => array( 'Show VAT-number summary on the order editing page' ), 'elite' => array( 'Show VAT-number summary on the order editing page' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-loading', 'label' => 'Where VAT checks load', 'consequence' => 'Choose where the VAT-checking script loads. Restricting it can leave a VAT field without its usual interactive check or progress messages on other forms.', 'context' => 'Open every form where you collect a VAT number after saving, including any enabled signup form. If its check stops working, return to the previous loading setting and inspect that form again.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-loading', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_messages_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_messages_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_messages_options_tab' ) ), 'members' => array( 'free' => array( 'Restrictive Loading (Free limit applies)' ), 'plus' => array( 'Restrictive Loading' ), 'elite' => array( 'Restrictive Loading' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-validation-exceptions', 'label' => 'Country validation exceptions', 'consequence' => 'Skip VAT validation for selected countries or adjust how country prefixes are handled. Skipping a check is not the same as confirming a number is valid.', 'context' => 'Check a selected country and one still requiring validation, including a number with its country prefix. Keep exemption choices separate. Restore the previous exceptions if a number bypasses a check unintentionally.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-validation-exceptions', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_advanced_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_advanced_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_advanced_options_tab' ) ), 'members' => array( 'free' => array( 'Skip VAT Validation for Selected Countries', 'Apply Country Code Prefix to EU VAT ' ), 'plus' => array( 'Skip VAT Validation for Selected Countries', 'Apply Country Code Prefix to EU VAT ' ), 'elite' => array( 'Skip VAT Validation for Selected Countries', 'Apply Country Code Prefix to EU VAT ' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-customer-sources', 'label' => 'Saved customer VAT numbers and signup', 'consequence' => 'Read VAT numbers saved in an older customer field when needed. Elite also offers signup collection and role-based field availability; those two options are not in Free or Plus.', 'context' => 'Check which saved customer field supplies the number before changing this choice. A stored number may never have been validated. Keep customer numbers private, and restore the previous saved-customer field if the expected number no longer appears.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-customer-sources', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_advanced_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_advanced_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_advanced_options_tab' ) ), 'members' => array( 'free' => array( 'Use VAT numbers from the previous saved-customer field' ), 'plus' => array( 'Use VAT numbers from the previous saved-customer field' ), 'elite' => array( 'Use VAT numbers from the previous saved-customer field', 'EU VAT Field by User Roles', 'Collect VAT on signup' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-tools', 'label' => 'VAT reference tool', 'consequence' => 'Open the VAT-rate reference tool for EU countries. A displayed reference rate does not decide which tax rules apply to your products or customers.', 'context' => 'Find the relevant country, then confirm the applicable rate and treatment with your tax adviser or official guidance. Leave tax settings unchanged until you have resolved any difference.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-tools', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_tool_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_tool_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number&active_tab=wcj_eu_vat_number_tool_options_tab' ) ), 'members' => array( 'free' => array( 'EU VAT-rate reference tool' ), 'plus' => array( 'EU VAT-rate reference tool' ), 'elite' => array( 'EU VAT-rate reference tool' ) ) ),
  array( 'module' => 'multicurrency_base_price', 'group' => 'base-update', 'label' => 'Base-currency rate updates', 'consequence' => 'Choose manual or automatic rates for converting prices entered in a product\'s base currency. Free uses manual updates; Plus and Elite offer automatic modes.', 'context' => 'Check the currency direction and saved rate after an update. If the provider fails, do not assume the previous rate is current; correct the rate or return to the prior update mode until the problem is resolved.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-product-base-price/#booster-v10-s18-base-update', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_general_options_tab' ) ), 'members' => array( 'free' => array( 'Exchange Rates Updates (Free limit applies)' ), 'plus' => array( 'Exchange Rates Updates' ), 'elite' => array( 'Exchange Rates Updates' ) ) ),
  array( 'module' => 'multicurrency_base_price', 'group' => 'base-rounding', 'label' => 'Base-currency rounding', 'consequence' => 'Round converted product prices to the chosen precision. This can change the amount, not just the number of digits shown.', 'context' => 'Compare a few low and high prices before and after saving, including sale prices. Restore the previous rounding choice if the resulting amounts or endings are not what you intend.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-product-base-price/#booster-v10-s18-base-rounding', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_general_options_tab' ) ), 'members' => array( 'free' => array( 'Round Prices', 'rounding precision' ), 'plus' => array( 'Round Prices', 'rounding precision' ), 'elite' => array( 'Round Prices', 'rounding precision' ) ) ),
  array( 'module' => 'multicurrency_base_price', 'group' => 'base-admin', 'label' => 'Administrative price display', 'consequence' => 'Show converted prices in the administration product list. This is a separate display choice from what a shopper sees in the store.', 'context' => 'Compare the product-list price with the product\'s entered price and its shop price. If the converted administration display is confusing, turn this option back off; do not overwrite the entered price just to match the display.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-product-base-price/#booster-v10-s18-base-admin', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_general_options_tab' ) ), 'members' => array( 'free' => array( 'Convert Product Prices in Admin Products List' ), 'plus' => array( 'Convert Product Prices in Admin Products List' ), 'elite' => array( 'Convert Product Prices in Admin Products List' ) ) ),
  array( 'module' => 'multicurrency_base_price', 'group' => 'base-storage', 'label' => 'Reuse calculated prices and choose calculation order', 'consequence' => 'Reuse converted prices while a page is being generated, or change when conversion runs relative to other price changes. Reusing a calculation does not rewrite the product\'s stored price; Priority controls calculation order and can affect the result.', 'context' => 'Note the current choices before changing them. Compare product and cart amounts with your other pricing features, then load a fresh page. Restore the previous choices if the result differs from the conversion you intend.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-product-base-price/#booster-v10-s18-base-storage', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_advanced_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_advanced_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_advanced_tab' ) ), 'members' => array( 'free' => array( 'Save Calculated Products Prices (reuse while a page loads)', 'Price Filters Priority (calculation order)' ), 'plus' => array( 'Save Calculated Products Prices (reuse while a page loads)', 'Price Filters Priority (calculation order)' ), 'elite' => array( 'Save Calculated Products Prices (reuse while a page loads)', 'Price Filters Priority (calculation order)' ) ) ),
  array( 'module' => 'multicurrency_base_price', 'group' => 'base-compatibility', 'label' => 'Price filter and sorting support', 'consequence' => 'Help WooCommerce price filtering and price sorting work with base-currency conversion. Correct display alone does not ensure products appear in the right price range or order.', 'context' => 'Check a price-range filter and low-to-high sorting after changing a conversion rate. If products appear in the wrong place, restore the previous option and review the store\'s saved price data with support.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-product-base-price/#booster-v10-s18-base-compatibility', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_compatibility_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_compatibility_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_compatibility_tab' ) ), 'members' => array( 'free' => array( 'WooCommerce Price Filter Compatibility', 'WooCommerce Price Sorting (Free limit applies)' ), 'plus' => array( 'WooCommerce Price Filter Compatibility', 'WooCommerce Price Sorting' ), 'elite' => array( 'WooCommerce Price Filter Compatibility', 'WooCommerce Price Sorting' ) ) ),
  array( 'module' => 'multicurrency_base_price', 'group' => 'base-currencies', 'label' => 'Available base currencies', 'consequence' => 'Choose the currencies in which product prices may be entered and the rates used to convert them. Free uses one currency row; Plus and Elite allow their configured rows.', 'context' => 'Check each row\'s currency and rate before saving. Include the intended base currency for your products, and check products with a blank choice or the store currency too. Restore previous rows if conversion changes unexpectedly.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-product-base-price/#booster-v10-s18-base-currencies', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_currencies_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_currencies_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price&active_tab=multicurrency_base_price_currencies_options_tab' ) ), 'members' => array( 'free' => array( 'Total Currencies (Free limit applies)', 'Currency', 'Conversion rate for each currency row' ), 'plus' => array( 'Total Currencies', 'Currency', 'Conversion rate for each currency row' ), 'elite' => array( 'Total Currencies', 'Currency', 'Conversion rate for each currency row' ) ) ),
  array( 'module' => 'multicurrency_base_price', 'group' => 'base-product', 'label' => 'This product base currency', 'consequence' => 'Choose the currency in which this product\'s entered price is expressed. This is the starting currency for conversion, not the shopper\'s preferred currency.', 'context' => 'Check that the entered regular and sale amounts use that currency. Then compare the converted shop and cart prices. Restore the previous currency and amounts together if you selected the wrong starting currency.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-product-base-price/#booster-v10-s18-base-product', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Product Currency' ), 'plus' => array( 'Product Currency' ), 'elite' => array( 'Product Currency' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-update', 'label' => 'Switcher rate updates', 'consequence' => 'Choose manual or automatic rate updates for the currency switcher. Free uses manual updates; Plus and Elite can use the available automatic modes.', 'context' => 'Check a saved rate after requesting or scheduling an update, then compare a converted product price. If a fetch fails, resolve the provider problem before treating the previous rate as current.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-update', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ) ), 'members' => array( 'free' => array( 'Exchange Rates Updates (Free limit applies)' ), 'plus' => array( 'Exchange Rates Updates' ), 'elite' => array( 'Exchange Rates Updates' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-product-mode', 'label' => 'Product-specific currency prices', 'consequence' => 'Allow products to have their own regular and sale prices for each currency. Empty-price and variation options can affect whether an item can be bought.', 'context' => 'Enable only the product-pricing options you need, save, and inspect a product and its variations. Check a currency with a price and one left empty. Keep the previous settings and amounts so you can restore unintended availability changes.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-product-mode', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ) ), 'members' => array( 'free' => array( 'Multicurrency on per Product Basis', 'Variable products: list available/active variations only', 'Add option to make empty price' ), 'plus' => array( 'Multicurrency on per Product Basis', 'Variable products: list available/active variations only', 'Add option to make empty price' ), 'elite' => array( 'Multicurrency on per Product Basis', 'Variable products: list available/active variations only', 'Add option to make empty price' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-revert', 'label' => 'Checkout currency reversion', 'consequence' => 'Choose whether the shopper\'s currency returns to the store default during checkout. The currency used for browsing may therefore differ from the currency used to pay.', 'context' => 'Choose the point where reversion should occur, then follow a test purchase from product to checkout. Check the currency beside the final total. Restore the previous choice if the switch would surprise your buyers.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-revert', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ) ), 'members' => array( 'free' => array( 'Revert Currency to Shop\'s Default' ), 'plus' => array( 'Revert Currency to Shop\'s Default' ), 'elite' => array( 'Revert Currency to Shop\'s Default' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-rounding', 'label' => 'Converted-price rounding', 'consequence' => 'Round converted amounts using the selected method and precision. Rounding changes the payable figures as well as their appearance.', 'context' => 'Compare regular prices, sale prices and a cart total in each offered currency. Restore the previous method if small prices or totals round in an unintended direction.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-rounding', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ) ), 'members' => array( 'free' => array( 'Rounding', 'Rounding Precision' ), 'plus' => array( 'Rounding', 'Rounding Precision' ), 'elite' => array( 'Rounding', 'Rounding Precision' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-template', 'label' => 'Currency switcher wording', 'consequence' => 'Choose how currency choices are labelled using the currency\'s name, code and symbol. Clear labels help buyers distinguish currencies that share a symbol.', 'context' => 'Use the listed placeholders to build the label, then view every switcher choice. Keep the currency code where a symbol could be ambiguous. Restore the previous template if any choice is blank or unclear.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-template', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ) ), 'members' => array( 'free' => array( 'Currency Switcher Template' ), 'plus' => array( 'Currency Switcher Template' ), 'elite' => array( 'Currency Switcher Template' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-shipping', 'label' => 'Shipping value conversion', 'consequence' => 'Choose whether shipping values are converted along with product prices. Shipping has its own conversion options and should not be assumed to follow product amounts automatically.', 'context' => 'Compare the shipping charge before and after switching currency, including any free-shipping threshold. Restore the previous conversion choice if the charge or eligibility changes unexpectedly.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-shipping', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_general_options_tab' ) ), 'members' => array( 'free' => array( 'Convert Shipping Values (Free limit applies)' ), 'plus' => array( 'Convert Shipping Values' ), 'elite' => array( 'Convert Shipping Values' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-compatibility', 'label' => 'Coupons shipping and plugin compatibility', 'consequence' => 'Adjust how switched currencies work with coupons, shipping, price sorting, imports and the listed product or pricing extensions. Each option addresses a different feature.', 'context' => 'Change only the option relevant to an installed feature. Check its amounts and thresholds in two currencies, including fixed coupons or add-on charges you use. Restore the previous option if totals or available choices become wrong.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-compatibility', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_compatobolity_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_compatobolity_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_compatobolity_tab' ) ), 'members' => array( 'free' => array( 'Free Shipping (Free limit applies)', 'WooCommerce Fixed Coupons', 'WooCommerce Coupons - Min & Max amount (Free limit applies)', 'WooCommerce Smart Coupons', 'WooCommerce Price Filter', 'Price Sorting with Per Product', 'WooCommerce Import', 'WPC Product Bundles', 'WooCommerce Tree Table Rate Shipping (Free limit applies)', 'Flexible Shipping (Free limit applies)', 'Pricing Deals Plugin (Free limit applies)', 'Product Add-Ons Plugin (Free limit applies)', 'WooCommerce Attribute Swatches by Iconic Plugin (Free limit applies)' ), 'plus' => array( 'Free Shipping', 'WooCommerce Fixed Coupons', 'WooCommerce Coupons - Min & Max amount', 'WooCommerce Smart Coupons', 'WooCommerce Price Filter', 'Price Sorting with Per Product', 'WooCommerce Import', 'WPC Product Bundles', 'WooCommerce Tree Table Rate Shipping', 'Flexible Shipping', 'Pricing Deals Plugin', 'Product Add-Ons Plugin', 'WooCommerce Attribute Swatches by Iconic Plugin' ), 'elite' => array( 'Free Shipping', 'WooCommerce Fixed Coupons', 'WooCommerce Coupons - Min & Max amount', 'WooCommerce Smart Coupons', 'WooCommerce Price Filter', 'Price Sorting with Per Product', 'WooCommerce Import', 'WPC Product Bundles', 'WooCommerce Tree Table Rate Shipping', 'Flexible Shipping', 'Pricing Deals Plugin', 'Product Add-Ons Plugin', 'WooCommerce Attribute Swatches by Iconic Plugin' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-advanced', 'label' => 'Extra calculations, price reuse and rate-change updates', 'consequence' => 'Choose extra places where conversion runs and its calculation order. Save Calculated Products Prices reuses amounts while a page loads; it does not rewrite product prices. The separate Save Prices on Exchange Update option queues updates to saved per-currency minimum and maximum product prices when a rate changes.', 'context' => 'Leave unfamiliar extra calculation entries unchanged and ask support which one is needed. Record the old choices. After changing a rate, compare products, variations and price ranges as well as cart amounts. Restore the prior options if results conflict; switching off rate-change updates does not undo minimum and maximum values already saved.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-advanced', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_advanced_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_advanced_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_advanced_tab' ) ), 'members' => array( 'free' => array( 'Additional Price Filters (extra places to convert prices)', 'Price Filters Priority (calculation order)', 'Save Prices on Exchange Update (update saved minimum and maximum prices)', 'Save Calculated Products Prices (reuse while a page loads)' ), 'plus' => array( 'Additional Price Filters (extra places to convert prices)', 'Price Filters Priority (calculation order)', 'Save Prices on Exchange Update (update saved minimum and maximum prices)', 'Save Calculated Products Prices (reuse while a page loads)' ), 'elite' => array( 'Additional Price Filters (extra places to convert prices)', 'Price Filters Priority (calculation order)', 'Save Prices on Exchange Update (update saved minimum and maximum prices)', 'Save Calculated Products Prices (reuse while a page loads)' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-currencies', 'label' => 'Switcher currencies and rates', 'consequence' => 'Choose the currencies and rates offered to shoppers. Free has two currency rows; Plus and Elite also offer currency selection based on the customer\'s estimated IP location.', 'context' => 'Check every code and rate, including rate 1 for a store-currency row. Save the list and switch between its choices on a product and in the cart. Confirm your payment provider supports them; restore the previous list if a needed currency disappears.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-currencies', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_currencies_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_currencies_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_currencies_options_tab' ) ), 'members' => array( 'free' => array( 'Total Currencies (Free limit applies)', 'Currency', 'Conversion rate for each currency row' ), 'plus' => array( 'Set Currency By Customer Country', 'Total Currencies', 'Currency', 'Conversion rate for each currency row' ), 'elite' => array( 'Set Currency By Customer Country', 'Total Currencies', 'Currency', 'Conversion rate for each currency row' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-default', 'label' => 'Default and forced currency', 'consequence' => 'Choose the starting currency and whether shoppers can switch away from it. A shopper who already chose a currency may keep that choice rather than receive a new default.', 'context' => 'Check both a new visit and a visit with a previous currency choice. If you force a currency, confirm the selector and checkout agree. Return to the previous setting if shoppers cannot choose an intended payment currency.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-default', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_default_currency_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_default_currency_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_default_currency_tab' ) ), 'members' => array( 'free' => array( 'Currency', 'Force' ), 'plus' => array( 'Currency', 'Force' ), 'elite' => array( 'Currency', 'Force' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-role-default', 'label' => 'Shopper role defaults', 'consequence' => 'Set a default currency for selected shopper roles, such as customers or wholesale buyers. These rules describe the shopper, not the product\'s author.', 'context' => 'Select the roles, save, and reopen settings to fill their currency choices. Check accounts with the relevant roles, including overlapping roles. Restore a role\'s previous default if it selects the wrong currency.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-role-default', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_role_default_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_role_default_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency&active_tab=multicurrency_role_default_tab' ) ), 'members' => array( 'free' => array( 'Roles', 'Default currency for each selected shopper role' ), 'plus' => array( 'Roles', 'Default currency for each selected shopper role' ), 'elite' => array( 'Roles', 'Default currency for each selected shopper role' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-product', 'label' => 'This product currency amounts', 'consequence' => 'Enter regular and sale prices for this product or variation in each offered currency. These explicit amounts can replace prices calculated from exchange rates; an empty-price choice can affect availability.', 'context' => 'Check the intended currency beside every amount, then inspect the product and each affected variation. Try adding them to a test cart. Restore the previous values or empty-price choice if an item becomes unavailable or wrongly priced.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-product', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Regular Price', 'Sale Price', 'Make Empty Price' ), 'plus' => array( 'Regular Price', 'Sale Price', 'Make Empty Price' ), 'elite' => array( 'Regular Price', 'Sale Price', 'Make Empty Price' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-widget', 'label' => 'Currency switcher widget', 'consequence' => 'Add a currency selector to a widget area and choose its title, layout and appearance. The widget changes the shopper\'s currency choice, not your saved exchange rates.', 'context' => 'Place it in an available sidebar and try each choice on the shop page. If your theme has no widget areas or uses a different editor, use the guide\'s alternative placement. Restore the earlier widget settings if its labels or selection stop working.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-widget', 'routes' => array( 'free' => array( 'widgets.php' ), 'plus' => array( 'widgets.php' ), 'elite' => array( 'widgets.php' ) ), 'members' => array( 'free' => array( 'Title', 'Type', 'Form Method (how the selector submits a choice)', 'CSS class (styling name)', 'CSS style (appearance rules)' ), 'plus' => array( 'Title', 'Type', 'Form Method (how the selector submits a choice)', 'CSS class (styling name)', 'CSS style (appearance rules)' ), 'elite' => array( 'Title', 'Type', 'Form Method (how the selector submits a choice)', 'CSS class (styling name)', 'CSS style (appearance rules)' ) ) ),
  array( 'module' => 'payment_gateways_currency', 'group' => 'gateway-rates', 'label' => 'Payment-method currency and rate', 'consequence' => 'Choose a currency and conversion rate for each payment method, or leave its currency unchanged. A payment method\'s actual accepted currencies are set by its provider, not by this selection.', 'context' => 'Confirm the provider accepts the chosen currency, then check the final total with that method selected on a test checkout. Keep the previous currency and rate so you can restore them if the payment total is wrong.', 'guide' => 'https://booster.io/docs/woocommerce-payment-gateways-currency-converter/#booster-v10-s18-gateway-rates', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency&active_tab=wcj_gateways_currency_converter_payment_gatways_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency&active_tab=wcj_gateways_currency_converter_payment_gatways_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency&active_tab=wcj_gateways_currency_converter_payment_gatways_tab' ) ), 'members' => array( 'free' => array( 'Go to payment gateway\'s settings', 'Conversion rate for each payment method' ), 'plus' => array( 'Go to payment gateway\'s settings', 'Conversion rate for each payment method' ), 'elite' => array( 'Go to payment gateway\'s settings', 'Conversion rate for each payment method' ) ) ),
  array( 'module' => 'payment_gateways_currency', 'group' => 'gateway-update', 'label' => 'Gateway rate updates', 'consequence' => 'Choose manual or automatic updates for payment-method conversion rates. Free uses manual updates; Plus and Elite can use the available automatic modes.', 'context' => 'Check the rate for each affected payment method after an update. If fetching fails or the rate is unsuitable, correct it and resolve the provider issue before relying on another automatic update.', 'guide' => 'https://booster.io/docs/woocommerce-payment-gateways-currency-converter/#booster-v10-s18-gateway-update', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency&active_tab=wcj_gateways_currency_converter_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency&active_tab=wcj_gateways_currency_converter_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency&active_tab=wcj_gateways_currency_converter_general_options_tab' ) ), 'members' => array( 'free' => array( 'Exchange Rates Updates (Free limit applies)' ), 'plus' => array( 'Exchange Rates Updates' ), 'elite' => array( 'Exchange Rates Updates' ) ) ),
  array( 'module' => 'payment_gateways_currency', 'group' => 'gateway-scope', 'label' => 'Where converted prices appear', 'consequence' => 'Choose where payment-method conversion applies and whether to use the selected-method compatibility fix. This can change which prices shoppers see before payment.', 'context' => 'Follow a test purchase through the selected pages and change the payment method at checkout. Compare its final total and currency with the provider\'s requirements. Restore the previous page choices or fix setting if totals disagree.', 'guide' => 'https://booster.io/docs/woocommerce-payment-gateways-currency-converter/#booster-v10-s18-gateway-scope', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency&active_tab=wcj_gateways_currency_converter_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency&active_tab=wcj_gateways_currency_converter_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency&active_tab=wcj_gateways_currency_converter_general_options_tab' ) ), 'members' => array( 'free' => array( 'Show Converted Prices', 'Advanced: Fix "Chosen Payment Method"' ), 'plus' => array( 'Show Converted Prices', 'Advanced: Fix "Chosen Payment Method"' ), 'elite' => array( 'Show Converted Prices', 'Advanced: Fix "Chosen Payment Method"' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-detection', 'label' => 'Country detection and override', 'consequence' => 'Choose how the store finds a shopper\'s country, including location detection, a country selector and checkout address overrides. The detected country is not proof of legal residence.', 'context' => 'Check a new visit, a manual country choice and different billing or shipping countries. If the wrong price group is selected, restore the previous detection setting and review the address override choices.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-detection', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ) ), 'members' => array( 'free' => array( 'Customer Country Detection Method', 'Override Country Options', 'Override Scope' ), 'plus' => array( 'Customer Country Detection Method', 'Override Country Options', 'Override Scope' ), 'elite' => array( 'Customer Country Detection Method', 'Override Country Options', 'Override Scope' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-checkout', 'label' => 'Checkout currency and country', 'consequence' => 'Choose whether checkout returns to the store currency and whether a default billing country is filled in automatically. Browsing country and checkout address can lead to different results.', 'context' => 'Follow a test purchase from the shop to checkout and change the billing country. Check the final currency and country fields. Restore the previous choices if an automatic value would mislead buyers.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-checkout', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ) ), 'members' => array( 'free' => array( 'Revert Currency to Default on Checkout', 'Auto set default checkout billing country' ), 'plus' => array( 'Revert Currency to Default on Checkout', 'Auto set default checkout billing country' ), 'elite' => array( 'Revert Currency to Default on Checkout', 'Auto set default checkout billing country' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-rounding', 'label' => 'Country price rounding', 'consequence' => 'Round country prices and optionally reduce them to a preferred ending. With Make Pretty Price enabled, Discount Min Amount Multiplier sets how many smallest units, such as cents, are subtracted.', 'context' => 'Compare several prices in each affected currency, especially small amounts. Check the final reduction as well as the rounded figure. Restore the prior rounding or multiplier if the ending or amount is wrong.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-rounding', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ) ), 'members' => array( 'free' => array( 'Price Rounding', 'Make Pretty Price', 'Discount Min Amount Multiplier' ), 'plus' => array( 'Price Rounding', 'Make Pretty Price', 'Discount Min Amount Multiplier' ), 'elite' => array( 'Price Rounding', 'Make Pretty Price', 'Discount Min Amount Multiplier' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-product-mode', 'label' => 'Product-specific country pricing', 'consequence' => 'Allow country-specific prices on individual products, choose the editing layout and choose which staff roles can see those controls. Product and variation prices can differ from the general country rate.', 'context' => 'Save the editing choices, then reopen a product using an intended staff account. Check its country prices and variations. Restore the earlier layout or role selection if staff cannot find the needed fields.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-product-mode', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ) ), 'members' => array( 'free' => array( 'Price by Country on per Product Basis', 'Per product options - backend style', 'Per product options - backend user role visibility' ), 'plus' => array( 'Price by Country on per Product Basis', 'Per product options - backend style', 'Per product options - backend user role visibility' ), 'elite' => array( 'Price by Country on per Product Basis', 'Per product options - backend style', 'Per product options - backend user role visibility' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-selector-bots', 'label' => 'Country selector and bots', 'consequence' => 'Show flags in the country selector and choose whether country pricing is disabled for detected search-engine bots. A bot may then see different prices from a shopper.', 'context' => 'Check the selector labels without relying only on flags. Review the bot choice before changing how prices are presented to search engines. Restore the previous choices if the selector becomes unclear or your intended price presentation changes.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-selector-bots', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_price_by_country_tab' ) ), 'members' => array( 'free' => array( 'Add Countries Flags Images to Select Drop-Down Box', 'Search Engine Bots' ), 'plus' => array( 'Add Countries Flags Images to Select Drop-Down Box', 'Search Engine Bots' ), 'elite' => array( 'Add Countries Flags Images to Select Drop-Down Box', 'Search Engine Bots' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-compatibility', 'label' => 'Country-price compatibility', 'consequence' => 'Adjust how country pricing works with the listed subscription, B2B, coupon, discount, shipping and rewards features. Quick Edit and price-filter options affect different parts of the store.', 'context' => 'Change only an option for a feature you use. Check that feature\'s price or threshold in two country groups, including any reward or shipping amount. Restore the prior option if another feature\'s result becomes wrong.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-compatibility', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_compatibiliry_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_compatibiliry_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_compatibiliry_tab' ) ), 'members' => array( 'free' => array( 'Active Webtofee subscription Section', 'Active B2B Plugin Price Section', 'Disable Quick Edit Product For Admin Scope', 'Price Filter Widget and Sorting by Price Support (Free limit applies)', 'Free Shipping (Free limit applies)', 'WooCommerce Coupons', 'Woo Discount Rules (Free limit applies)', 'WooCommerce Points and Rewards (Free limit applies)' ), 'plus' => array( 'Active Webtofee subscription Section', 'Active B2B Plugin Price Section', 'Disable Quick Edit Product For Admin Scope', 'Price Filter Widget and Sorting by Price Support', 'Free Shipping', 'WooCommerce Coupons', 'Woo Discount Rules', 'WooCommerce Points and Rewards' ), 'elite' => array( 'Active Webtofee subscription Section', 'Active B2B Plugin Price Section', 'Disable Quick Edit Product For Admin Scope', 'Price Filter Widget and Sorting by Price Support', 'Free Shipping', 'WooCommerce Coupons', 'Woo Discount Rules', 'WooCommerce Points and Rewards' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-advanced', 'label' => 'Country detection, calculation order and price reuse', 'consequence' => 'Choose how to read the shopper\'s IP address, how to format prices and when country pricing runs. Priority means calculation order. Save Calculated Products Prices and Save Country Group ID reuse the price or matched group while a page loads; those options do not rewrite product prices or permanently choose the shopper\'s country.', 'context' => 'Record the old choices. Check an affected product and cart after changing country and loading a fresh page. If a group or amount is wrong, restore the previous choices and review country detection and any other pricing features.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-advanced', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_advanced_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_advanced_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_advanced_tab' ) ), 'members' => array( 'free' => array( 'Price Filters Priority (calculation order)', 'User IP Detection Method (how to read the shopper address)', 'Price Format Method', 'Save Calculated Products Prices (reuse while a page loads)', 'Save Country Group ID (reuse the matched group while a page loads)' ), 'plus' => array( 'Price Filters Priority (calculation order)', 'User IP Detection Method (how to read the shopper address)', 'Price Format Method', 'Save Calculated Products Prices (reuse while a page loads)', 'Save Country Group ID (reuse the matched group while a page loads)' ), 'elite' => array( 'Price Filters Priority (calculation order)', 'User IP Detection Method (how to read the shopper address)', 'Price Format Method', 'Save Calculated Products Prices (reuse while a page loads)', 'Save Country Group ID (reuse the matched group while a page loads)' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-group-shape', 'label' => 'Country group selection and generation', 'consequence' => 'Choose how countries are selected, how many groups to use and whether to generate groups automatically. Generating groups replaces group settings; it is not a preview or an Undo action.', 'context' => 'Record the current groups before generating replacements or reducing their count. Free uses one group. After saving, check which countries and currencies are in every group; restore your recorded settings if a needed group was replaced.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-group-shape', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_country_groups_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_country_groups_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_country_groups_tab' ) ), 'members' => array( 'free' => array( 'Countries Selection', 'Autogenerate Groups', 'Groups Number (Free limit applies)' ), 'plus' => array( 'Countries Selection', 'Autogenerate Groups', 'Groups Number' ), 'elite' => array( 'Countries Selection', 'Autogenerate Groups', 'Groups Number' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-groups', 'label' => 'Country group membership and currency', 'consequence' => 'Assign countries, a currency and an administration label to each group. The country-selection style determines which country field you use; the alternative lists are not separate groups.', 'context' => 'Check for countries missing from, or included in more than one, group. Try a country from each group and compare its currency. Restore the prior membership if a country receives the wrong prices; generation is a separate replacement action.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-groups', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_country_groups_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_country_groups_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_country_groups_tab' ) ), 'members' => array( 'free' => array( 'Countries (comma-separated codes). Country codes and sets: https://booster.io/country-codes/', 'Countries selected for each group', 'Currency', 'Admin Title' ), 'plus' => array( 'Countries (comma-separated codes). Country codes and sets: https://booster.io/country-codes/', 'Countries selected for each group', 'Currency', 'Admin Title' ), 'elite' => array( 'Countries (comma-separated codes). Country codes and sets: https://booster.io/country-codes/', 'Countries selected for each group', 'Currency', 'Admin Title' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-rates', 'label' => 'Country rates and empty prices', 'consequence' => 'Set the conversion rate for each country group and choose manual or automatic updates. A Make Empty Price choice can remove a price and affect whether a product can be bought.', 'context' => 'Check one product and a test cart for each group, including any group with empty prices. Free uses manual rates. Correct or restore the previous rate or empty-price choice if amounts or availability are not intended.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-rates', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_exchange_rates_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_exchange_rates_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country&active_tab=price_by_country_exchange_rates_tab' ) ), 'members' => array( 'free' => array( 'Exchange Rates Updates (Free limit applies)', 'Group', 'Make empty price' ), 'plus' => array( 'Exchange Rates Updates', 'Group', 'Make empty price' ), 'elite' => array( 'Exchange Rates Updates', 'Group', 'Make empty price' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-product', 'label' => 'Product and variation group prices', 'consequence' => 'Enter regular and sale prices for this product or variation by country group. These amounts can replace general conversions, and an empty-price choice can affect whether the item can be bought.', 'context' => 'Check the group label beside each amount and try each affected variation. Compare the shop and cart after selecting that country. Restore the previous amounts or empty-price choice if the product is wrongly priced or unavailable.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-product', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Regular price', 'Sale price', 'Make empty price' ), 'plus' => array( 'Regular price', 'Sale price', 'Make empty price' ), 'elite' => array( 'Regular price', 'Sale price', 'Make empty price' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-inline-product', 'label' => 'Inline country product prices', 'consequence' => 'Edit a product\'s country-group regular and sale prices in the inline layout. These are the same country-price choices available through the other product-editing layout, not extra independent prices.', 'context' => 'Check the group beside the amount and any empty-price choice before saving. Reopen the product and inspect it for that country. Restore the prior values if changing layouts made you edit the wrong group.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-inline-product', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Regular Price', 'Sale Price', 'Make empty price' ), 'plus' => array( 'Regular Price', 'Sale Price', 'Make empty price' ), 'elite' => array( 'Regular Price', 'Sale Price', 'Make empty price' ) ) ),
  array( 'module' => 'price_formats', 'group' => 'format-trim', 'label' => 'Trim trailing price zeros', 'consequence' => 'Remove unnecessary zeros at the end of displayed prices. This is separate from choosing a currency\'s decimal precision.', 'context' => 'Compare whole amounts and prices with meaningful decimal digits after saving. If the shortened appearance is confusing, turn trimming off again rather than changing the underlying price.', 'guide' => 'https://booster.io/docs/woocommerce-price-formats/#booster-v10-s18-format-trim', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_formats&active_tab=price_formats_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_formats&active_tab=price_formats_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_formats&active_tab=price_formats_general_options_tab' ) ), 'members' => array( 'free' => array( 'Trim Zeros in Prices' ), 'plus' => array( 'Trim Zeros in Prices' ), 'elite' => array( 'Trim Zeros in Prices' ) ) ),
  array( 'module' => 'price_formats', 'group' => 'format-rows', 'label' => 'Currency-specific number formats', 'consequence' => 'Set currency-symbol and code placement, separators, decimal precision and optional WPML language matching for each format row. Decimal precision can change rounded amounts, not just appearance.', 'context' => 'Free uses one row. Check large and small amounts, sale prices and a cart total in each matched currency or language. Restore the prior precision or separators if amounts or currency labels become ambiguous.', 'guide' => 'https://booster.io/docs/woocommerce-price-formats/#booster-v10-s18-format-rows', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_formats&active_tab=price_formats_price_formats_by_currency_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_formats&active_tab=price_formats_price_formats_by_currency_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_formats&active_tab=price_formats_price_formats_by_currency_tab' ) ), 'members' => array( 'free' => array( 'Price Formats by Currency (or WPML)', 'Total Number (Free limit applies)', 'Format', 'Currency Position', 'Additional Currency Code Position', 'Thousand Separator', 'Decimal Separator', 'Number of Decimals', 'WPML Language Code (language to match)' ), 'plus' => array( 'Price Formats by Currency (or WPML)', 'Total Number', 'Format', 'Currency Position', 'Additional Currency Code Position', 'Thousand Separator', 'Decimal Separator', 'Number of Decimals', 'WPML Language Code (language to match)' ), 'elite' => array( 'Price Formats by Currency (or WPML)', 'Total Number', 'Format', 'Currency Position', 'Additional Currency Code Position', 'Thousand Separator', 'Decimal Separator', 'Number of Decimals', 'WPML Language Code (language to match)' ) ) ),
  array( 'module' => 'tax_display', 'group' => 'tax-toggle', 'label' => 'Shopper tax display toggle', 'consequence' => 'Let shoppers choose prices including or excluding tax with a display toggle. This changes presentation, not tax rates or whether a shopper is tax-exempt.', 'context' => 'Enable the toggle and add its shortcode where shoppers can use it. Compare a product and cart before and after switching. Remove the shortcode or restore the prior toggle setting if the displayed choice is confusing.', 'guide' => 'https://booster.io/docs/woocommerce-tax-display/#booster-v10-s18-tax-toggle', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display&active_tab=wcj_product_tax_display_toggle_button_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display&active_tab=wcj_product_tax_display_toggle_button_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display&active_tab=wcj_product_tax_display_toggle_button_tab' ) ), 'members' => array( 'free' => array( 'TAX Toggle Button' ), 'plus' => array( 'TAX Toggle Button' ), 'elite' => array( 'TAX Toggle Button' ) ) ),
  array( 'module' => 'tax_display', 'group' => 'tax-products', 'label' => 'Product tax display', 'consequence' => 'Choose whether selected products or categories show prices including or excluding tax. This does not change their tax rates. Overlapping selections can make the displayed result less obvious.', 'context' => 'Check products inside and outside each selection, including when no individual products are selected. If a category or exclusion does not behave as expected, restore the prior display choices rather than changing tax rates to compensate.', 'guide' => 'https://booster.io/docs/woocommerce-tax-display/#booster-v10-s18-tax-products', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display&active_tab=wcj_product_tax_display_by_product_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display&active_tab=wcj_product_tax_display_by_product_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display&active_tab=wcj_product_tax_display_by_product_tab' ) ), 'members' => array( 'free' => array( 'TAX Display by Product', 'Products - Including TAX', 'Products - Excluding TAX', 'Product Categories - Including TAX', 'Product Categories - Excluding TAX' ), 'plus' => array( 'TAX Display by Product', 'Products - Including TAX', 'Products - Excluding TAX', 'Product Categories - Including TAX', 'Product Categories - Excluding TAX' ), 'elite' => array( 'TAX Display by Product', 'Products - Including TAX', 'Products - Excluding TAX', 'Product Categories - Including TAX', 'Product Categories - Excluding TAX' ) ) ),
  array( 'module' => 'tax_display', 'group' => 'tax-roles', 'label' => 'Role-specific tax display', 'consequence' => 'Choose separate shop and cart tax displays for selected shopper roles. With multiple roles, the first matching role that specifies a display choice can determine the result.', 'context' => 'Select roles, save, and fill in the settings that appear for them. Check an account with each role and an account with overlapping roles. Restore the previous role choices if shop and cart displays do not agree with your intention.', 'guide' => 'https://booster.io/docs/woocommerce-tax-display/#booster-v10-s18-tax-roles', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display&active_tab=wcj_product_tax_display_by_user_role_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display&active_tab=wcj_product_tax_display_by_user_role_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display&active_tab=wcj_product_tax_display_by_user_role_tab' ) ), 'members' => array( 'free' => array( 'TAX Display by User Role', 'User Roles', 'Tax display for each selected role: shop', 'Tax display for each selected role: cart' ), 'plus' => array( 'TAX Display by User Role', 'User Roles', 'Tax display for each selected role: shop', 'Tax display for each selected role: cart' ), 'elite' => array( 'TAX Display by User Role', 'User Roles', 'Tax display for each selected role: shop', 'Tax display for each selected role: cart' ) ) ),
  array( 'module' => 'currency_exchange_rates', 'group' => 'rates-update-now', 'label' => 'Update rates now', 'consequence' => 'Fetch rates now for the enabled features that use automatic updates. This contacts rate providers and can replace rates used by more than one currency feature.', 'context' => 'Note the current rates before using Update now. After it finishes, inspect the affected pairs and prices. If fetching fails, check the provider and connection details; do not treat an unchanged old rate as a successful refresh.', 'guide' => 'https://booster.io/docs/woocommerce-currency-exchange-rates/#booster-v10-s18-rates-update-now', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_exchange_rates' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_exchange_rates' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_exchange_rates' ) ), 'members' => array( 'free' => array( 'Update exchange rates now' ), 'plus' => array( 'Update exchange rates now' ), 'elite' => array( 'Update exchange rates now' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-order-action', 'label' => 'Order VAT validation and tax removal', 'consequence' => 'Validate the order\'s VAT number and, when applicable, remove taxes from that existing order. This can change the order total; it is not a harmless check.', 'context' => 'Keep a record of the order\'s amounts and tax lines first. After using the action, inspect the tax lines and total before sending an updated invoice or requesting payment. If wrong, correct the order through its editor; the symbol task\'s Undo cannot restore order taxes.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-order-action', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Validate VAT number and remove order taxes' ), 'plus' => array( 'Validate VAT number and remove order taxes' ), 'elite' => array( 'Validate VAT number and remove order taxes' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'vat-customer-field', 'label' => 'Customer and checkout VAT field', 'consequence' => 'Collect or edit a VAT number in customer billing, checkout or order details. Elite can also collect it at signup and limit the field by role; those two options are not in Free or Plus.', 'context' => 'Check the number\'s country prefix and the form where it was entered. A saved number is not automatically a successful validation. Correct an incorrect number in the appropriate customer or order record, and keep it private.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-vat-customer-field', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'VAT number in customer, checkout and order details' ), 'plus' => array( 'VAT number in customer, checkout and order details' ), 'elite' => array( 'VAT number in customer, checkout and order details' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multi-shortcodes', 'label' => 'Currency selection shortcodes', 'consequence' => 'Place a currency dropdown, radio list or link list using a shortcode, which is a small bracketed instruction added to page content. Choosing an option changes that shopper\'s currency choice.', 'context' => 'Use the setup guide to choose the shortcode and placement. Check a new visit and an existing currency choice, including any forced or role-based default. Remove the added shortcode or restore its prior options if shoppers cannot switch as intended.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multi-shortcodes', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Currency dropdown, radio and link-list shortcodes' ), 'plus' => array( 'Currency dropdown, radio and link-list shortcodes' ), 'elite' => array( 'Currency dropdown, radio and link-list shortcodes' ) ) ),
  array( 'module' => 'currency', 'group' => 'currency-shortcodes', 'label' => 'Current currency output', 'consequence' => 'Display the current currency code or symbol using a shortcode, which is a small bracketed instruction placed in content. Its result follows the currency active on that page; it does not fetch a rate or confirm payment support.', 'context' => 'Check the output on a fresh page and after switching currency. If it shows an unexpected currency, review the active currency settings before changing the wording. Remove or restore the shortcode if it labels the wrong amount.', 'guide' => 'https://booster.io/docs/woocommerce-all-currencies/#booster-v10-s18-currency-shortcodes', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Current currency code and symbol shortcodes' ), 'plus' => array( 'Current currency code and symbol shortcodes' ), 'elite' => array( 'Current currency code and symbol shortcodes' ) ) ),
  array( 'module' => 'currency_exchange_rates', 'group' => 'rate-shortcodes', 'label' => 'Saved-rate shortcodes', 'consequence' => 'Show a saved exchange rate or rate table using a shortcode placed in content. Displaying a saved rate does not refresh it or confirm that a scheduled update succeeded.', 'context' => 'Check the displayed currency pair and compare it with the saved rate and your provider\'s current rate. If the value is stale, resolve the update problem or remove the display until it is suitable; do not present it as a live quote.', 'guide' => 'https://booster.io/docs/woocommerce-currency-exchange-rates/#booster-v10-s18-rate-shortcodes', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Saved rate and rate-table shortcodes' ), 'plus' => array( 'Saved rate and rate-table shortcodes' ), 'elite' => array( 'Saved rate and rate-table shortcodes' ) ) ),
  array( 'module' => 'tax_display', 'group' => 'tax-shortcode', 'label' => 'Tax display toggle shortcode', 'consequence' => 'Add a button that lets shoppers switch the tax display between including and excluding tax. Enabling the feature does not place the button on a page automatically.', 'context' => 'Add the shortcode from the setup guide, then click the button and check product and cart displays. It does not change tax liability. Remove the shortcode or restore the prior options if the label or display is misleading.', 'guide' => 'https://booster.io/docs/woocommerce-tax-display/#booster-v10-s18-tax-shortcode', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Tax display toggle shortcode' ), 'plus' => array( 'Tax display toggle shortcode' ), 'elite' => array( 'Tax display toggle shortcode' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'country-shortcode', 'label' => 'Country selector shortcode', 'consequence' => 'Add a country selector using a shortcode placed in content. The choice can change the shopper\'s country-price group; a currency label is not proof of the shopper\'s location.', 'context' => 'Place the selector where shoppers can find it, then choose countries from different groups and check product and cart prices. Restore the previous shortcode options or group membership if a choice shows the wrong currency.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-country-shortcode', 'routes' => array( 'free' => array(  ), 'plus' => array(  ), 'elite' => array(  ) ), 'members' => array( 'free' => array( 'Country selector shortcode' ), 'plus' => array( 'Country selector shortcode' ), 'elite' => array( 'Country selector shortcode' ) ) ),
  array( 'module' => 'currency', 'group' => 'currency-state', 'label' => 'Module state and reset', 'consequence' => 'Turn currency-symbol changes on or off. Your saved symbol choices are separate from whether the Currencies module is running. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check the module switch and Hide Currency Symbol before expecting a changed symbol to appear. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-all-currencies/#booster-v10-s18-currency-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) ),
  array( 'module' => 'currency_exchange_rates', 'group' => 'currency-exchange-rates-state', 'label' => 'Module state and reset', 'consequence' => 'Turn the exchange-rate module on or off. A saved provider or schedule alone does not mean updates are running. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check which other enabled currency features use these rates before changing this switch. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-currency-exchange-rates/#booster-v10-s18-currency-exchange-rates-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_exchange_rates' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_exchange_rates' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_exchange_rates' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) ),
  array( 'module' => 'currency_external_products', 'group' => 'currency-external-products-state', 'label' => 'Module state and reset', 'consequence' => 'Turn the external-product currency display on or off. This does not control the seller at the destination of the Buy button. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check an external product and its destination listing after changing the switch. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-currency-for-external-products/#booster-v10-s18-currency-external-products-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_external_products' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_external_products' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_external_products' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) ),
  array( 'module' => 'currency_per_product', 'group' => 'currency-per-product-state', 'label' => 'Module state and reset', 'consequence' => 'Turn product-currency rules on or off. This can change which currency or conversion a product and cart use. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check products with different currencies and any mixed-currency cart restriction after changing the switch. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-currency-per-product/#booster-v10-s18-currency-per-product-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=currency_per_product' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) ),
  array( 'module' => 'eu_vat_number', 'group' => 'eu-vat-number-state', 'label' => 'Module state and reset', 'consequence' => 'Turn VAT-number features on or off. Saved field, validation and exemption choices do not by themselves mean those features are running. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check checkout and any customer or signup forms you use, and review the resulting tax treatment. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-eu-vat-number/#booster-v10-s18-eu-vat-number-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=eu_vat_number' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) ),
  array( 'module' => 'multicurrency', 'group' => 'multicurrency-state', 'label' => 'Module state and reset', 'consequence' => 'Turn the currency switcher and its conversion features on or off. Saved currencies and rates are separate from this switch. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check the selector, product prices, shipping and final checkout currency after changing it. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-currency-switcher/#booster-v10-s18-multicurrency-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) ),
  array( 'module' => 'multicurrency_base_price', 'group' => 'multicurrency-base-price-state', 'label' => 'Module state and reset', 'consequence' => 'Turn conversion from product base currencies on or off. Products entered in a different currency may display different amounts when this changes. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check products with different base currencies and their cart amounts before relying on the new setting. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-multicurrency-product-base-price/#booster-v10-s18-multicurrency-base-price-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=multicurrency_base_price' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) ),
  array( 'module' => 'payment_gateways_currency', 'group' => 'payment-gateways-currency-state', 'label' => 'Module state and reset', 'consequence' => 'Turn payment-method currency conversion on or off. Saved method rates do not confirm that conversion is active or that a provider accepts the currency. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check a test checkout with each affected payment method after changing the switch. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-payment-gateways-currency-converter/#booster-v10-s18-payment-gateways-currency-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=payment_gateways&section=payment_gateways_currency' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) ),
  array( 'module' => 'price_by_country', 'group' => 'price-by-country-state', 'label' => 'Module state and reset', 'consequence' => 'Turn country-based prices and currencies on or off. Saved country groups are separate from whether those rules are applied. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check a shopper from each affected group and the final checkout currency after changing the switch. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-prices-and-currencies-by-country/#booster-v10-s18-price-by-country-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_by_country' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) ),
  array( 'module' => 'price_formats', 'group' => 'price-formats-state', 'label' => 'Module state and reset', 'consequence' => 'Turn the currency-specific price formats on or off. Symbol placement and decimal precision can differ when these formats are not applied. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check large and small amounts in each affected currency, including rounded cart totals. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-price-formats/#booster-v10-s18-price-formats-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_formats' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_formats' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=prices_and_currencies&section=price_formats' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) ),
  array( 'module' => 'tax_display', 'group' => 'tax-display-state', 'label' => 'Module state and reset', 'consequence' => 'Turn the selected product, role and shopper-toggle tax displays on or off. This does not set tax rates or decide exemption policy. Reset erases this module\'s saved settings; it is not Undo.', 'context' => 'Check shop and cart displays for the selected products and shopper roles after changing the switch. Record the current settings before resetting so you can restore the choices you need.', 'guide' => 'https://booster.io/docs/woocommerce-tax-display/#booster-v10-s18-tax-display-state', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=products&section=tax_display' ) ), 'members' => array( 'free' => array( 'Module on/off and reset settings' ), 'plus' => array( 'Module on/off and reset settings' ), 'elite' => array( 'Module on/off and reset settings' ) ) )
 ); }
 public static function modules(){return array( 'currency' => array( 'Currencies', 'shown', 'Symbols label amounts. Defining a custom currency does not convert prices or make a payment provider accept it.', 'Free cannot edit ordinary currency symbols and supports one custom currency. Plus and Elite can edit ordinary symbols and use their configured custom-currency slots.' ), 'currency_exchange_rates' => array( 'Currency exchange rates', 'conversion', 'Choose a rate provider and update schedule for the currency features that use them. Check the saved rates after an expected update; a schedule alone does not mean a fetch succeeded.', 'Free permits one custom currency selection here. Automatic-update availability also depends on the currency feature using these rates.' ), 'currency_external_products' => array( 'External product currency', 'shown', 'Choose the currency shown on external products. The purchase happens at another seller, so check that seller\'s amount and payment currency too.', 'The currency selector is available in Free, Plus and Elite.' ), 'currency_per_product' => array( 'Currency per product', 'conversion', 'Assign currencies to products or matching authors, categories and tags. Cart restrictions can stop shoppers combining different products or currencies.', 'Free uses one currency row and manual updates. Plus and Elite support their configured rows and available automatic-update modes.' ), 'eu_vat_number' => array( 'EU VAT number', 'tax', 'Collect and check VAT numbers. A valid number does not by itself remove VAT; your exemption choices and customer conditions still matter.', 'Signup collection and VAT field role controls are Elite only. Free and Plus have other VAT-number settings, with the limits shown beside each setting.' ), 'multicurrency' => array( 'Multicurrency switcher', 'conversion', 'Let shoppers choose a currency. Check converted amounts, shipping and the currency accepted by the payment provider separately.', 'Free uses two currency rows and manual updates. Selection by customer IP location is available in Plus and Elite. Other edition limits are shown beside the relevant settings.' ), 'multicurrency_base_price' => array( 'Multicurrency product base price', 'conversion', 'Enter product prices in a base currency and convert them using your rates. Rounding can change amounts; calculation reuse does not rewrite the entered product price.', 'Free uses one currency row and manual updates. Plus and Elite support their configured rows and available automatic-update modes.' ), 'payment_gateways_currency' => array( 'Payment gateway currency conversion', 'conversion', 'Convert amounts for the chosen payment method. Confirm the provider accepts that currency and check its final payment total.', 'Free uses manual rate updates. Plus and Elite offer the available automatic-update modes.' ), 'price_by_country' => array( 'Prices and currencies by country', 'conversion', 'Choose country groups, currencies and prices. Generating groups replaces group settings. If you use other currency features, compare product and checkout amounts for each affected country.', 'Free uses one country group and manual rates. Plus and Elite support their configured groups and available automatic-update modes; individual setting limits still apply.' ), 'price_formats' => array( 'Price formats', 'shown', 'Choose symbol placement, separators and decimal precision. Precision can change rounded amounts, so check totals as well as appearance.', 'Free uses one format row. Plus and Elite support their configured format rows.' ), 'tax_display' => array( 'Tax display', 'shown', 'Choose whether selected products or shopper roles see prices including or excluding tax. This does not set tax rates or decide who is exempt.', 'These settings are available in all editions. Save your product or role selections, then complete the matching display choices.' ) );}
 public static function url(){return admin_url('admin.php?page=wcj-currency-tax-tasks');}
 public static function allowed($module){$core=WCJ_Job_Store::core();return WCJ_Task_Finder::allowed($module)&&$core&&isset($core->all_modules[$module]);}
 private static function link($url,$label){return '<a target="_blank" rel="noopener noreferrer" href="'.esc_url($url).'">'.esc_html($label.' (new tab)').'</a>';}
 public static function render($module='',$selected=array()){
  $items=array_filter(self::groups(),static function($g)use($module,$selected){return (!$module||$module===$g['module'])&&(!$selected||in_array($g['group'],$selected,true))&&self::allowed($g['module']);});
  if(!$items){return;}$ed=WCJ_Currency_Symbol_Job::edition();
  echo '<details class="wcj-currency-groups"><summary>Currency and tax: settings and help</summary><p>Help and full settings open in a new tab, leaving unsaved edits here. If you change settings there, save them, then reload this page. Opening a link does not switch on a module, fetch rates, check a VAT number, generate country groups or change an order.</p><ul>';
  foreach($items as $g){
   echo '<li class="wcj-currency-group" data-currency-group="'.esc_attr($g['group']).'"><h4>'.esc_html($g['label']).'</h4><p>'.esc_html($g['consequence']).'</p>';
   if($g['context']){echo '<p>'.esc_html($g['context']).'</p>';}
   echo '<p>';foreach(array_unique($g['routes'][$ed]) as $route){echo self::link(admin_url($route),'Full settings: '.$g['label']).' | ';}echo self::link($g['guide'],'Help: '.$g['label']).'</p>';
   if($g['members'][$ed]){echo '<details><summary>Settings listed for '.esc_html(ucfirst($ed)).'</summary><ul>';foreach($g['members'][$ed] as $label){echo '<li>'.esc_html($label).'</li>';}echo '</ul><p>The fields you can use depend on this edition and your earlier choices. Save a changed count or selection, then reopen settings to see any additional rows. A listed setting may still be unavailable to your account.</p></details>';}
   echo '</li>';
  }echo '</ul></details>';
 }
 public static function entry(){if(current_user_can('manage_woocommerce')){echo '<p><a href="'.esc_url(self::url()).'">Currency and tax: choose what to change</a></p>';}}
 public static function register(){if(current_user_can('manage_woocommerce')){add_submenu_page('woocommerce','Currency and tax choices','Currency and tax','manage_woocommerce','wcj-currency-tax-tasks',array(__CLASS__,'hub'));}}
 /** Saved flags only, never inferred execution order or effective currency/tax. */
 public static function inventory(){
  if(!current_user_can('manage_woocommerce')){return;}echo '<details class="wcj-currency-inventory"><summary>Modules saved as On or Off</summary><p>This list shows saved On/Off choices. It does not tell you which currency or tax a shopper will see. Check an affected product and checkout when several features are enabled.</p>';
  foreach(array('shown'=>'How prices are shown','conversion'=>'Currency and conversion','tax'=>'Tax and VAT') as $lane=>$label){echo '<h3>'.esc_html($label).'</h3><ul>';foreach(self::modules() as $id=>$m){if($lane!==$m[1]||!self::allowed($id)){continue;}$s=WCJ_Job_Store::read_state('wcj_'.$id.'_enabled');$flag=!$s['exists']?'Off (not switched on)':('yes'===$s['raw']?'On':('no'===$s['raw']?'Off':'Unrecognized saved value'));echo '<li>'.esc_html($m[0].': '.$flag).'</li>';}echo '</ul>';}
  echo '</details>';
 }
 public static function hub(){
  if(!current_user_can('manage_woocommerce')){wp_die(esc_html__('Ask an administrator for access.','woocommerce-jetpack'));}
  wp_enqueue_style('wcj-currency-symbol-job',wcj_plugin_url().'/assets/css/admin/wcj-currency-symbol-job.css',array(),'1.0');
  echo '<div class="wrap wcj-currency-hub"><h1>Use the right currency and tax treatment</h1><p>Choose what you want to change. A currency symbol labels an amount; conversion changes the amount; payment currency and tax rules are separate choices.</p>';
  if(self::allowed('currency')){echo '<p><a class="button button-primary" href="'.esc_url(WCJ_Currency_Symbol_Job::url()).'">Change the symbol for your store currency</a></p>';}
  foreach(array('shown'=>'How prices are shown','conversion'=>'Currency and conversion','tax'=>'Tax and VAT') as $lane=>$label){echo '<section><h2>'.esc_html($label).'</h2>';foreach(self::modules() as $id=>$m){if($lane!==$m[1]||!self::allowed($id)){continue;}echo '<div data-currency-module="'.esc_attr($id).'"><h3>'.esc_html($m[0]).'</h3><p>'.esc_html($m[2]).'</p><p>'.esc_html($m[3]).'</p>';self::render($id);echo '</div>';}echo '</section>';}
  self::inventory();echo '</div>';
 }
 public static function product_boxes($type,$post){
  if(!current_user_can('manage_woocommerce')||!is_object($post)||!current_user_can('edit_post',$post->ID)){return;}
  if('product'===$type){add_meta_box('wcj-currency-product-help','Currency settings: help and consequences',array(__CLASS__,'product_help'),'product','normal','low');}
  elseif(in_array($type,array('post','page'),true)&&preg_match('/\[wcj_(?:currency|exchange_rate|multicurrency|country|tax)/',(string)$post->post_content)){add_meta_box('wcj-currency-shortcode-help','Currency and tax shortcode help',array(__CLASS__,'shortcode_help'),$type,'side','low');}
 }
 public static function product_help($post){if(!current_user_can('manage_woocommerce')||!current_user_can('edit_post',$post->ID)){return;}echo '<p>The fields available here depend on the enabled modules, product type and product-editing choices. These help links do not change the product\'s price or currency.</p>';self::render('',array('product-currency-meta','base-product','multi-product','country-product','country-inline-product'));}
 public static function variation_help(){if(current_user_can('manage_woocommerce')){self::render('',array('base-product','multi-product','country-product'));}}
 public static function shortcode_help(){self::render('',array('multi-shortcodes','currency-shortcodes','rate-shortcodes','tax-shortcode','country-shortcode'));}
 public static function customer_help($user){if(!is_object($user)||!current_user_can('edit_user',$user->ID)){return;}self::render('eu_vat_number',array('vat-customer-field','vat-customer-sources'));}
 public static function screen_help(){
  if(!current_user_can('manage_woocommerce')){return;}$screen=get_current_screen();if(!$screen){return;}
  if('widgets'===$screen->id){self::render('multicurrency',array('multi-widget'));}
  elseif(in_array($screen->id,array('shop_order','woocommerce_page_wc-orders'),true)&&current_user_can('edit_shop_orders')){self::render('eu_vat_number',array('vat-order-action'));}
  elseif('woocommerce_page_wc-settings'===$screen->id&&(!isset($_GET['tab'])||(is_string($_GET['tab'])&&'general'===$_GET['tab']))){self::render('currency',array('store-symbol'));}
 }
}
add_action('admin_menu',array('WCJ_Currency_Tax_Groups','register'),99);
add_action('add_meta_boxes',array('WCJ_Currency_Tax_Groups','product_boxes'),40,2);
add_action('woocommerce_variation_options_pricing',array('WCJ_Currency_Tax_Groups','variation_help'),40);
add_action('show_user_profile',array('WCJ_Currency_Tax_Groups','customer_help'),40);
add_action('edit_user_profile',array('WCJ_Currency_Tax_Groups','customer_help'),40);
add_action('admin_notices',array('WCJ_Currency_Tax_Groups','screen_help'),40);
